      '[nombre], eres el hueco que queda cuando alguien importante se va. Y ni así se te nota. Puto relleno con nombre y sin una sola cosa dentro.',
      '[nombre], perdedor de los que ni se reciclan. Tu inutilidad es estructural y tu conformismo vocacional. La gente se aparta por instinto, no por juicio.',
