      'Puto don nadie, [nombre]. Ni te odian ni te quieren. Simplemente estás, como el mueble del pasillo que nadie mira y que todos esquivan al pasar.',
      'Eres el fracaso normalizado, [nombre]. Ya ni se comenta, se asume. Como el moho de la pared: está, huele, y nadie tiene ganas de hacer nada al respecto.',
      '[nombre], la gente ya no espera nada de ti, y eso es la forma más educada que existe de decir que te han descartado del todo. Cabrón, ni te has enterado.',
