      'Puta mierda de trayectoria, [nombre]. Si te quitamos las promesas incumplidas no queda una sola línea. Ni un logro, ni una excusa nueva.',
      '[nombre], eres el mueble del pasillo: nadie te mira, todos te esquivan y nadie te mueve porque da pereza. Un don nadie con foto de perfil.',
      'Perdedor por diseño, [nombre]. Cada atajo que cogiste te trajo justo aquí, al fondo, con el resto de la basura y sin nadie que te eche de menos.',
      'Eres un fracasado con opinión, [nombre], que es la peor clase que existe. No has hecho nada y aun así opinas de lo que hacen los demás.',
      '[nombre], tu autoestima es lo único tuyo que no ha bajado y eso dice más de tu ceguera que de tu valor. Un idiota convencido, lo más patético que hay.',
      'Perdedor sin herederos, [nombre]: nadie quiere tu sitio, tu método ni tu puesto. Cuando te vayas la silla se queda vacía y nadie preguntará por ti.',
      '[nombre], puto don nadie: ni te odian ni te quieren. Simplemente estás ahí, ocupando línea en la lista y sin justificar el ancho que gastas.',
      '[nombre], tu currículum vital cabe en un post-it y sobra sitio para dibujar la cara que pones cuando alguien pregunta a qué te dedicas.',
      'Eres el gorrón que se sienta a la mesa, come de todo y desaparece cuando llega la cuenta, [nombre]. Mismo perfil, otra pantalla, la misma basura.',
      '[nombre], perdedor con la piel muy fina y el expediente muy sucio. Te ofendes por todo sin haber hecho nada que justifique una sola ofensa.',
      'Tu marcador parece una condena, [nombre], y la firmaste tú. Nadie te obligó a nada. Elegiste esta mierda, decisión tras decisión, durante años.',
      '[nombre], eres el error que ya nadie corrige porque no merece el esfuerzo. Ni la gente que te aprecia se molesta. Puto agotamiento colectivo.',
      '[nombre], eres el hueco que queda cuando alguien importante se va. Y ni así se nota que estás. Puto relleno con nombre y sin nada dentro.',
      '[nombre], perdedor con la constancia de un reloj roto: siempre la misma hora de mierda y sin que nadie se moleste ya en cambiarle la pila.',
      'Eres un desperdicio con antigüedad, [nombre]. Años aquí sin dejar una sola marca que justifique el sitio que ocupas. Ni un mensaje que valga.',
      '[nombre], eres el que se apunta a todo y no termina nada. Y encima te ofende que se note. Puta lista de intentos sin una sola casilla marcada.',
      'Perdedor de manual, [nombre]: tu mayor talento es encontrar razones por las que no era el momento. Nunca es el momento, cabrón.',
      'Eres el que pide otra oportunidad justo después de gastar la última, [nombre]. Y la pides con esa voz. Puta vergüenza cada vez.',
      '[nombre], perdedor con memoria corta para lo suyo y larguísima para lo ajeno. Muy conveniente y muy patético al mismo tiempo.',
      'Perdedor de saldo, [nombre]: nadie te ha cerrado ninguna puerta. Es que nunca llamaste a ninguna. Ahí está todo tu problema.',
      '[nombre], has convertido el casi en tu dirección postal. Casi lo consigues, casi llegas, casi vales. Puta biografía en condicional.',
      'Eres el único que sigue creyendo en tu potencial, [nombre]. El resto lo enterramos hace años y sin ceremonia, muerto de hambre.',
      'Tu presencia en cualquier reparto es lo primero que sobra, [nombre]. Y el reparto lo hacen personas que te conocen bien. Piénsalo.',
      '[nombre], eres el que se retira antes de que le echen y lo llama decisión propia. Nadie se traga eso, pringado. Ni tú por la noche.',
      'Perdedor de manual, [nombre], con la piel muy fina y ni un solo logro que justifique tanta susceptibilidad. Puta combinación insufrible.',
      'Eres el peso que este grupo carga por costumbre, [nombre]. No por afecto. Y la costumbre también se acaba, muerto de hambre.',
      'Tu problema es que crees que insistir basta, [nombre]. Hay que insistir en algo que sirva, cabrón, y tú insistes en ser esto.',
      'Perdedor con la constancia de una gotera, [nombre]: siempre ahí, siempre igual y nadie con ganas de llamar al fontanero.',
      'Perdedor de saldo, [nombre]: nadie te ha cerrado ninguna puerta porque nunca llamaste a ninguna. Ahí está tu problema entero.',
      '[nombre], has convertido el casi en tu dirección postal. Casi llegas, casi vales, casi cuentas. Puta biografía en condicional.',
      '[nombre], tu presencia en cualquier reparto es lo primero que sobra. Y el reparto lo hace gente que te conoce bien. Piénsalo.',
      '[nombre], hablas del futuro para no hablar del presente. Y el futuro llega y sigues en el mismo puto sitio de siempre.',
      'Eres el peso que este grupo carga por costumbre, [nombre]. No por afecto. Y la costumbre también se acaba, cabrón.',
      '[nombre], perdedor con la constancia de una gotera: siempre ahí, siempre igual y nadie con ganas de llamar al fontanero.',
      '[nombre], eres el que se retira antes de que le echen y lo llama decisión propia. Nadie se traga eso. Ni tú por la noche, pringado.',
      'Perdedor de manual, [nombre]: te apuntas a todo y no terminas nada. Y encima te ofende que se note. Puta cara dura sin resultados.',
      '[nombre], perdedor con la estrategia de esperar a ver qué pasa. Nunca pasa nada bueno y encima te sorprende. Puta paciencia mal invertida.',
      'Eres el que no deja huella ni cuando pisa barro, [nombre]. Un peso pluma en un grupo donde ya casi nadie pesa. Miseria sobre miseria.',
      'Tu problema no es de suerte ni de contexto, [nombre]. Es estructural y viene de fábrica. Naciste con esta mierda puesta y ni la has mirado.',
      'Perdedor de manual, [nombre]: te apuntas a todo y no terminas nada. Y encima te ofende que se note. Puta cara dura sin un solo resultado detrás.',
      'Eres el que pide otra oportunidad justo después de gastar la última, [nombre]. Y la pides con esa voz. Puta vergüenza ajena cada vez que abres la boca.',
      '[nombre], perdedor con memoria corta para lo suyo y larguísima para lo ajeno. Muy conveniente y muy patético al mismo tiempo, cabrón.',
      'Tu vida es una lista de cosas que ibas a hacer, [nombre]. La lista es lo único completado y ni eso está bien escrito. Puto borrador permanente.',
      '[nombre], eres el que se compara hacia abajo para poder dormir. Y aun así duermes mal, porque sabes exactamente la mierda que hay debajo.',
      'Perdedor de saldo, [nombre]: nadie te ha cerrado ninguna puerta porque nunca llamaste a ninguna. Ahí está tu problema entero y sin adornos.',
      '[nombre], has convertido el casi en tu dirección postal. Casi llegas, casi vales, casi cuentas. Puta biografía escrita entera en condicional.',
      '[nombre], tu presencia en cualquier reparto es lo primero que sobra. Y el reparto lo hace gente que te conoce bien. Piénsalo un segundo.',
