    mid: [
      'Ni perdedor del todo ni alguien que sume. Te quedas en esa franja tibia donde no haces daño pero tampoco haces falta, y eso a la larga pesa más de lo que crees.',
      'Tienes destellos de no ser un desastre, rodeados de decisiones que te devuelven al montón. Medio perdedor, medio salvable, y nadie sabe nunca cuál de los dos va a aparecer.',
      'No eres el peor, pero tampoco das motivos para que cuenten contigo. Perdedor a ratos, funcional a ratos, sin una línea clara entre las dos cosas.',
      'A veces pareces tener las cosas claras y a veces te hundes solo. Esa inconsistencia es justo lo que te deja a medio camino de ser un perdedor entero.',
      'Ni arriba ni abajo. Cumples lo mínimo para no ser señalado y nunca lo suficiente para que nadie te defienda. La zona más anónima que existe.',
      'Tienes con qué no ser un perdedor, pero lo desperdicias con una constancia que llama la atención. Potencial sin uso es casi peor que no tener nada.',
      'Medio perdedor por elección propia. Cuando te lo propones no estás mal; el problema es que proponértelo es justo lo raro en ti.',
      'No molestas ni aportas. Estás en ese punto medio donde la gente ni te suma ni te resta, simplemente te tolera por inercia.',
      'Ni ganas ni pierdes: sobrevives. Y sobrevivir sin avanzar acaba pareciéndose mucho a perder.',
      'Estás en el punto donde nadie te señala ni te elige. Cómodo hoy, caro dentro de unos años.',
      'Tienes momentos buenos que no encadenas. El talento suelto no sirve de nada si nunca se acumula.',
      'No eres un desastre, pero tampoco una garantía. La gente te tiene en la lista larga, nunca en la corta.',
      'Fallas justo lo suficiente para que nadie confíe del todo y aciertas lo justo para que no te descarten.',
      'Perdedor a media jornada. Cuando te concentras funcionas; el problema es que concentrarte te dura poco.',
      'Estás en tierra de nadie: demasiado capaz para dar pena, demasiado inconstante para dar seguridad.',
      'Ni arrastras al grupo ni tiras de él. Ocupas sitio y cumples, que es lo mínimo exigible.',
      'Tienes con qué salir de la mediocridad y ninguna urgencia por hacerlo. Eso es lo que te frena.',
      'Medio perdedor, medio decente. Depende del día, del ánimo y de si alguien te está mirando.',
      'No te falta capacidad, te falta continuidad. Y la continuidad es justo lo que separa a unos de otros.',
      'Cumples cuando es fácil y desapareces cuando aprieta. Por eso te quedas siempre en el medio.',
      'Nadie te va a defender ni a atacar. Estás en el punto exacto donde uno se vuelve invisible.',
      'Tienes suficientes aciertos para no ser un fracaso y suficientes fallos para no ser nadie de referencia.',
      'A veces das el nivel y a veces das vergüenza ajena. El promedio te deja justo aquí.',
      'Ni bien ni mal: regular sostenido. Es el resultado más difícil de defender y el más fácil de olvidar.',
      'Te falta ese punto de exigencia contigo mismo. Sin él, esto es exactamente hasta donde llegas.',
      'Estás en el montón por decisión propia, aunque lo llames circunstancias.',
      'Ni perdedor ni ganador: pasajero. La gente pasa por tu lado y no se le queda nada.',
      'Haces lo justo para que no te digan nada y nunca lo suficiente para que digan algo bueno.',
      'Tienes días de sobra y días de menos. El problema es que los de menos son bastantes más.',
      'No eres el problema del grupo, pero tampoco parte de la solución. Estás en el reparto de fondo.',
      'Medio perdedor con potencial de dejar de serlo. Llevas años en esa misma frase.',
      'Ni sobresales ni molestas. Es un equilibrio cómodo y absolutamente estéril.',
      'Tienes la capacidad justa para saber que podrías más. Y ese saber sin hacer es lo que pesa.',
      'Cumples el expediente y nada más. Un aprobado raspado sostenido en el tiempo.',
      'A ratos pareces alguien de fiar y a ratos justo lo contrario. Esa duda es tu marca.',
      'Ni una cosa ni la otra. Estás en la franja donde la gente ni te recomienda ni te desaconseja.',
      'Tienes buena base y mala gestión. Con lo primero se llega lejos; con lo segundo, hasta aquí.',
      'Perdedor a medias porque nunca te comprometes del todo con nada, ni siquiera con perder.',
      'Ni fracaso ni referencia. Un intermedio largo que ya empieza a parecer definitivo.',
      'Haces lo suficiente para seguir, nunca lo suficiente para destacar. Y así van pasando los meses.',
      'No eres de los que hunden un proyecto ni de los que lo levantan. Eres de los que están.',
      'Te falta hambre, no herramientas. Y el hambre no se enseña ni se presta.',
      'Medio salvable. Con constancia serías otro; sin ella, seguirás siendo exactamente este.',
      'Ni te señalan ni te buscan. Estás en el punto ciego del grupo y ni te has dado cuenta.',
      'Tienes aciertos que nadie recuerda y fallos que nadie comenta. Eso es la definición de tibio.',
      'No eres un perdedor, eres un pendiente. Y los pendientes se resuelven o se archivan.',
      'A medio camino de todo. Ni suficiente para presumir ni tan poco como para preocuparse.',
      'Ni bien ni mal, solo constante. Y la constancia sin dirección no lleva a ningún sitio.',
      'Perdedor intermitente. Cuando funcionas, funcionas; el problema es la palabra cuando.',
      'Estás justo en el borde. Un poco más de trabajo y sales; un poco menos y te hundes del todo.',
    ],
