      '[nombre], eres de los que hacen que un problema deje de parecerlo solo con ponerse a ello.',
      'Ganador sin público y sin necesitarlo, [nombre]. Los resultados no dependen de quién esté mirando.',
      '[nombre], la gente que trabaja contigo mejora. Y eso no se puede fingir ni una semana.',
      'Eres de los que se hacen responsables antes de que se lo pidan, [nombre]. Escaso y decisivo.',
