      'Tienes con qué liderar y prefieres no hacerlo. Es tu derecho, pero tiene un precio.',
      'Ganador a medias porque nunca te comprometes del todo. Ni con ganar ni con nada.',
      'Estás justo en la frontera. Un poco más de constancia y cambias de categoría entera.',
      'Ni ganas ni pierdes: mantienes. Y mantener durante demasiado tiempo se parece a estancarse.',
